head.script:
scwin.screenId = "jldinf92200";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf92200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf92200.btn_print_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_self_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_self_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_self_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92200.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = async function () {
    /* sdd-asis-lifecycle:begin fn_print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("지표 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        $.ajax({ type: "POST", async: false, url: "/srch/srch.do?method=srchReportCommonAjax&serviceName=srchReport13&std_cd=" + std_cd, data: {  }, success: async function(data) {
                    const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    const form = (document.newReportForm || { elements: [] });
                    for (key in result) {
                        if (form[camelize(key)]) {
                            form[camelize(key)].value = result[key];
                        }
                    }
                    await scwin.tx_fn_print();
                }, error: async function(request, status, error) {
                    await $c.win.alert("장애발생.");
                    return;
                }, complete: function() {

                } });
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.printOld
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.printOld = async function () {
    /* sdd-asis-lifecycle:begin fn_print_old — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("지표 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const formName = (document.JLDINF92200 || { elements: [] });
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        const rexName = "JLDINF92200";
        const dataType = "XML";
        const dataLocation = "/srch/srch.do?method=srchReport13&std_cd=" + std_cd;
        const dataXPath = "main/rpt1";
        const mktGubun = "1";
        fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);
    }
    /* sdd-asis-lifecycle:end */
};
